	internal VisibleWorldWindow GetVisibleWorldWindow()
	{
		var fallback = new VisibleWorldWindow(_viewW / 2, _viewH / 2);
		if (_subViewport == null || _camera == null)
			return fallback;

		return VoxelViewportMath.CalculateVisibleWorldWindow(
			_subViewport.Size,
			_camera.Zoom,
			fallback);
	}

	internal VisibleDepthWindow GetVisibleDepthWindow(VisibleWorldWindow? visibleWorldWindow = null)
	{
		var fallback = new VisibleDepthWindow(VoxelViewportMath.DefaultViewDepthAbove, VoxelViewportMath.DefaultViewDepthBelow);
		if (_subViewport == null || _camera == null)
			return fallback;

		var resolvedVisibleWorldWindow = visibleWorldWindow ?? GetVisibleWorldWindow();
		return VoxelViewportMath.CalculateVisibleDepthWindow(
			_subViewport.Size,
			_camera.Zoom,
			resolvedVisibleWorldWindow,
			fallback);
	}

	private Rect2? GetVisibleMapRect()
	{
		if (_subViewport == null || _camera == null)
			return null;

		return VoxelViewportMath.CalculateVisibleMapRect(
			_subViewport.Size,
			_camera.Position,
			_camera.Zoom);
	}

