	internal void PresentActorMotion(ActorMotionPresentationRequest request)
	{
		if (string.IsNullOrWhiteSpace(request.ActorId))
			return;

		if (!ShouldAnimateActorMotion(request))
		{
			ClearActorMotion(request.ActorId);
			return;
		}

		_motionTracker.Record(
			request.ActorId,
			request.SourceX,
			request.SourceY,
			request.SourceZ,
			request.TargetX,
			request.TargetY,
			request.TargetZ,
			_tileAnimationClockSeconds,
			request.DurationSecondsOverride ?? ActorMotionTiming.ResolveDurationSeconds(request.TimingTier),
			request.Blocking);
	}

	internal void ClearActorMotion(string actorId)
	{
		_motionTracker.Remove(actorId);
	}

	internal void ResetActorMotionState()
	{
		_motionTracker.Clear();
	}

	internal Vector3 ResolveActorVisualWorldPosition(string actorId)
	{
		var actor = ActorModule.GetById(_state, actorId);
		return actor == null ? Vector3.Zero : ResolveActorVisualWorldPosition(actor);
	}

	internal Vector2 ResolveRuntimeCameraScreenTarget() =>
		ResolveRuntimeCameraTarget(_viewCenterX, _viewCenterY, _viewCenterZ);

	public void Flush()
	{
		var frameStartUsec = Time.GetTicksUsec();
		_tileDrawCommandCount = 0;
		_weatherFxController?.BeginFrame();

		if (_state.World == null)
		{
			ResetActorMotionState();
			_weatherFxController?.ClearScreenFxTarget();
			_weatherFxController?.UpdateWeatherScreenFxOverlay(0d, _tileAnimationClockSeconds);
			_weatherFxController?.EndFrame();
			CommitPerfFrame((Time.GetTicksUsec() - frameStartUsec) / 1000.0);
			return;
		}

		if (_editorViewActive)
		{
			_fogTracker.RevealAll = true;
			_weatherFxController?.ClearScreenFxTarget();
		}
		else
		{
			_fogTracker.RevealAll = false;
			_fogTracker.Update(_state);
			_weatherFxController?.RefreshWeatherScreenFxTarget(editorViewActive: false);
			if (!_runtimeViewActive)
			{
				_viewCenterX = _state.PlayerX;
				_viewCenterY = _state.PlayerY;
				_viewCenterZ = _state.PlayerZ;
				_runtimeCameraView = RuntimeCameraSnapshot.Create(
					RuntimeCameraMode.FollowActor,
					_viewCenterX,
					_viewCenterY,
					_viewCenterZ);
			}
		}

		Render();
		_tileDrawCommandCount = _lastDrawCommandCount;
		_weatherFxController?.UpdateWeatherScreenFxOverlay(0d, _tileAnimationClockSeconds);
		_weatherFxController?.EndFrame();
		_motionTracker.Prune(_tileAnimationClockSeconds);
		CommitPerfFrame((Time.GetTicksUsec() - frameStartUsec) / 1000.0);
	}

	public void AdvanceAnimations(double delta)
	{
		if (delta <= 0d) return;
		_tileAnimationClockSeconds += delta;
		_weatherFxController?.UpdateWeatherScreenFxOverlay(delta, _tileAnimationClockSeconds);
		AdvancePlayerCorrectionSmoothing((float)delta);
		_motionTracker.UpdateBlockingFlag(_tileAnimationClockSeconds);
		AdvanceEditorCameraSmoothing((float)delta);
	}

	private bool ShouldAnimateActorMotion(ActorMotionPresentationRequest request)
	{
		if (!ActorMotionTracker.IsStandardStep(request))
			return false;

		if (string.Equals(request.ActorId, PartyModule.GetActiveId(_state), StringComparison.Ordinal))
			return true;

		return IsActorMotionRenderable(request.SourceX, request.SourceY, request.SourceZ)
			|| IsActorMotionRenderable(request.TargetX, request.TargetY, request.TargetZ);
	}

	private bool IsActorMotionRenderable(int worldX, int worldY, int worldZ)
	{
		var visibleWindow = GetVisibleWorldWindow();
		var visibleDepth = GetVisibleDepthWindow(visibleWindow);
		var zMin = _viewCenterZ - visibleDepth.Above;
		var zMax = _viewCenterZ + visibleDepth.Below;
		return Math.Abs(worldX - _viewCenterX) <= visibleWindow.HalfX + 1
			&& Math.Abs(worldY - _viewCenterY) <= visibleWindow.HalfY + 1
			&& worldZ >= zMin
			&& worldZ <= zMax
			&& _fogTracker.GetVisionBand(worldX, worldY, worldZ) != PlayerVisionBand.Unknown;
	}

	private Vector3 ResolveActorVisualWorldPosition(Actor actor)
	{
		return _motionTracker.TryGetInterpolatedPosition(actor.Id, _tileAnimationClockSeconds, out var position)
			? position
			: new Vector3(actor.X, actor.Y, actor.Z);
	}

	private void AdvanceEditorCameraSmoothing(float delta)
	{
		if (_camera == null || _editorCameraTarget is not { } target)
			return;

		var current = _camera.Position;
		if (current.DistanceSquaredTo(target) < 0.5f)
		{
			_camera.Position = target;
			return;
		}

		_camera.Position = current.Lerp(target, Mathf.Clamp(EditorCameraLerpSpeed * delta, 0f, 1f));
	}

	public bool IsWorldCellVisible(int wx, int wy, int wz)
	{
		if (_state.World == null) return false;
		var band = _fogTracker.GetVisionBand(wx, wy, wz);
		return band is PlayerVisionBand.Focused or PlayerVisionBand.Peripheral;
	}

	public bool TryGetWorldCellFromGlobalPosition(Vector2 globalPos, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (!TryGetMapLocalFromGlobalPosition(globalPos, out var mapLocal))
			return false;

		return TryPickIsometricCell(mapLocal, out worldCell);
	}

	public bool TryGetInspectWorldCellFromGlobalPosition(Vector2 globalPos, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (!TryGetMapLocalFromGlobalPosition(globalPos, out var mapLocal))
			return false;

		return TryPickInspectCell(mapLocal, out worldCell);
	}

	public bool TryGetEditorWorldCellFromGlobalPosition(Vector2 globalPos, int targetZ, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (!TryGetMapLocalFromGlobalPosition(globalPos, out var mapLocal))
			return false;

		return TryPickEditorCell(mapLocal, targetZ, out worldCell);
	}

	private bool TryGetMapLocalFromGlobalPosition(Vector2 globalPos, out Vector2 mapLocal)
	{
		mapLocal = Vector2.Zero;
		if (_viewportContainer == null || _subViewport == null || _camera == null)
			return false;

		var rect = _viewportContainer.GetGlobalRect();
		if (!rect.HasPoint(globalPos) || rect.Size.X <= 0 || rect.Size.Y <= 0)
			return false;

		var localInContainer = globalPos - rect.Position;
		var viewportPos = new Vector2(
			localInContainer.X * _subViewport.Size.X / rect.Size.X,
			localInContainer.Y * _subViewport.Size.Y / rect.Size.Y);
		var viewportSize = new Vector2(_subViewport.Size.X, _subViewport.Size.Y);
		var screenOffset = viewportPos - viewportSize / 2f;
		mapLocal = ResolveMapCameraPosition() + new Vector2(
			screenOffset.X / _camera.Zoom.X,
			screenOffset.Y / _camera.Zoom.Y);
		return true;
	}

	public bool TryGetMapLocalDeltaFromGlobalMotion(Vector2 globalMotion, out Vector2 mapLocalDelta)
	{
		mapLocalDelta = Vector2.Zero;
		if (_viewportContainer == null || _subViewport == null || _camera == null)
			return false;

		var rect = _viewportContainer.GetGlobalRect();
		if (rect.Size.X <= 0f || rect.Size.Y <= 0f || _camera.Zoom.X == 0f || _camera.Zoom.Y == 0f)
			return false;

		mapLocalDelta = new Vector2(
			globalMotion.X * _subViewport.Size.X / rect.Size.X / _camera.Zoom.X,
			globalMotion.Y * _subViewport.Size.Y / rect.Size.Y / _camera.Zoom.Y);
		return true;
	}

	private Vector2 ResolveMapCameraPosition()
	{
		if (_editorViewActive && _camera != null)
			return _camera.Position;
		if (_runtimeViewActive)
			return ResolveRuntimeCameraScreenTarget();
		return _camera?.Position ?? Vector2.Zero;
	}

	private bool TryPickIsometricCell(Vector2 screenPos, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (_state.World == null) return false;

		if (_runtimeViewActive)
		{
			var (runtimeX, runtimeY) = IsoCoordUtil.ScreenToWorldCell(screenPos, _runtimeCameraView.CenterZ);
			worldCell = new Vector3I(runtimeX, runtimeY, _runtimeCameraView.CenterZ);
			return true;
		}

		var cz = _editorViewActive ? _viewCenterZ : _state.PlayerZ;
		var visibleDepth = GetVisibleDepthWindow();
		var zMin = cz - visibleDepth.Above;
		var zMax = cz + visibleDepth.Below;
		for (var z = zMax; z >= zMin; z--)
		{
			var (wx, wy) = IsoCoordUtil.ScreenToWorldCell(screenPos, z);
			var terrain = _state.World.GetTerrain(wx, wy, z);
			if (terrain.StringId != Terrains.Air && terrain.StringId != Terrains.Void)
			{
				worldCell = new Vector3I(wx, wy, z);
				return true;
			}
		}

		// Editor mode: allow targeting empty cells at camera Z for block placement
		if (_editorViewActive)
		{
			var (fallbackX, fallbackY) = IsoCoordUtil.ScreenToWorldCell(screenPos, cz);
			worldCell = new Vector3I(fallbackX, fallbackY, cz);
			return true;
		}

		return false;
	}

	private bool TryPickEditorCell(Vector2 screenPos, int targetZ, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (_state.World == null)
			return false;

		var (wx, wy) = IsoCoordUtil.ScreenToWorldCell(screenPos, targetZ);
		worldCell = new Vector3I(wx, wy, targetZ);
		return true;
	}

	private bool TryPickInspectCell(Vector2 screenPos, out Vector3I worldCell)
	{
		worldCell = Vector3I.Zero;
		if (_state.World == null)
			return false;

		if (!_runtimeViewActive)
			return TryPickIsometricCell(screenPos, out worldCell);

		var visibleWindow = GetVisibleWorldWindow();
		var visibleDepth = GetVisibleDepthWindow(visibleWindow);
		var zMin = _runtimeCameraView.CenterZ - visibleDepth.Below;
		var zMax = _runtimeCameraView.CenterZ + visibleDepth.Above;
		Vector3I? bestNonEmptyCell = null;
		for (var z = zMax; z >= zMin; z--)
		{
			var (wx, wy) = IsoCoordUtil.ScreenToWorldCell(screenPos, z);
			if (!IsWorldCellVisible(wx, wy, z))
				continue;

			var cell = new Vector3I(wx, wy, z);
			if (ActorModule.GetAllAt(_state, wx, wy, z).Count > 0)
			{
				worldCell = cell;
				return true;
			}

			var items = _state.World.PeekGroundItems(wx, wy, z);
			if (items.Exists(static item => item.IsCorpse))
			{
				worldCell = cell;
				return true;
			}

			if (bestNonEmptyCell == null && HasInspectableCellContent(wx, wy, z))
				bestNonEmptyCell = cell;
		}

		if (bestNonEmptyCell is { } resolvedCell)
		{
			worldCell = resolvedCell;
			return true;
		}

		var (fallbackX, fallbackY) = IsoCoordUtil.ScreenToWorldCell(screenPos, _runtimeCameraView.CenterZ);
		worldCell = new Vector3I(fallbackX, fallbackY, _runtimeCameraView.CenterZ);
		return true;
	}

	private bool HasInspectableCellContent(int wx, int wy, int wz)
	{
		if (_state.World == null)
			return false;

		var terrain = _state.World.GetTerrain(wx, wy, wz).StringId;
		if (terrain is not (Terrains.Air or Terrains.Void))
			return true;
		if (!string.IsNullOrWhiteSpace(_state.World.GetFixtureId(wx, wy, wz)))
			return true;
		if (_state.World.GetEntities(wx, wy, wz).Count > 0)
			return true;
		if (FireSystem.GetFireIntensityAt(_state, wx, wy, wz) > 0)
			return true;

		return false;
	}

	public bool TryGetWorldEffectPosition(int wx, int wy, int wz, out Vector2 position)
	{
		position = IsoCoordUtil.WorldToScreen(wx, wy, wz);
		return true;
	}

	public bool TryGetWorldOverlayPosition(int wx, int wy, int wz, out Vector2 position)
	{
		position = Vector2.Zero;
		var mapPos = IsoCoordUtil.WorldToScreen(wx, wy, wz);
		return TryMapToOverlayPosition(mapPos, out position);
	}

	private bool TryMapToOverlayPosition(Vector2 mapPosition, out Vector2 overlayPosition)
	{
		overlayPosition = Vector2.Zero;
		if (_camera == null || _subViewport == null || _viewportContainer == null)
			return false;

		var viewportSize = new Vector2(_subViewport.Size.X, _subViewport.Size.Y);
		if (viewportSize.X <= 0f || viewportSize.Y <= 0f)
			return false;

		var zoom = _camera.Zoom;
		var viewportPosition = viewportSize / 2f + new Vector2(
			(mapPosition.X - _camera.Position.X) * zoom.X,
			(mapPosition.Y - _camera.Position.Y) * zoom.Y);
		var containerSize = _viewportContainer.Size;
		if (containerSize.X <= 0f || containerSize.Y <= 0f)
			return false;

		overlayPosition = new Vector2(
			viewportPosition.X * containerSize.X / viewportSize.X,
			viewportPosition.Y * containerSize.Y / viewportSize.Y);
		return true;
	}

	public bool StepZoom(int direction)
	{
		if (_camera == null || direction == 0)
			return false;
		var requestedZoom = Mathf.Clamp(_zoom + direction * CameraZoomStep, _minCameraZoom, _maxCameraZoom);
		if (Mathf.IsEqualApprox(requestedZoom, _zoom))
			return false;
		_zoom = requestedZoom;
		UpdateCameraZoom();
		return true;
	}

	public void SetZoomRange(float minZoom, float maxZoom)
	{
		var normalizedMin = Mathf.Clamp(minZoom, 0.2f, 4.0f);
		var normalizedMax = Mathf.Clamp(maxZoom, 0.2f, 4.0f);
		if (normalizedMin > normalizedMax)
			(normalizedMin, normalizedMax) = (normalizedMax, normalizedMin);
		_minCameraZoom = normalizedMin;
		_maxCameraZoom = normalizedMax;
		_zoom = Mathf.Clamp(_zoom, _minCameraZoom, _maxCameraZoom);
		UpdateCameraZoom();
	}

	public bool SetZoomTo(float zoom)
	{
		if (_camera == null) return false;
		var clamped = Mathf.Clamp(zoom, _minCameraZoom, _maxCameraZoom);
		if (Mathf.IsEqualApprox(clamped, _zoom)) return false;
		_zoom = clamped;
		UpdateCameraZoom();
		return true;
	}

	private void UpdateCameraZoom()
	{
		if (_camera != null)
			_camera.Zoom = Vector2.One * _zoom;
	}

